export const EXAM_BANK=Object.freeze(DATA.flatMap(([unit,key,...items])=>items.map((row,i)=>{const [prompt,...tail]=row;const rationale=tail.pop();return Object.freeze({id:`REF-F-${unit}-${i+1}`,topic:unit.slice(0,3),unit,tests:unit,module:`module-${unit.slice(1,3)}`,teaches:`module-${unit.slice(1,3)}.md#${unit.toLowerCase()}`,prompt,choices:Object.freeze(tail),correctChoice:0,rationale,...assessmentSource(unit,prompt,S[key])});})));
export const FINAL_EXAM_BANK=EXAM_BANK;
if(EXAM_BANK.length!==148||new Set(EXAM_BANK.map(q=>q.id)).size!==148)throw Error('REF final bank count');
for(const u of ALL_UNITS)if(EXAM_BANK.filter(q=>q.unit===u.code).length!==2)throw Error(`REF final unit coverage ${u.code}`);
for(const q of EXAM_BANK)if(q.choices.length!==4||new Set(q.choices).size!==4||q.correctChoice!==0||!q.rationale)throw Error(`REF final schema ${q.id}`);
export default EXAM_BANK;
